import{_ as t,d as o,e as i,x as a}from"./chunks/framework.BRr8VP3a.js";const u=JSON.parse('{"title":"Trace affected positions proportionately without shrinking protection","description":"A stopping rule for further inquiry is not a license to omit known people or lower their safeguards.","frontmatter":{"title":"Trace affected positions proportionately without shrinking protection","description":"A stopping rule for further inquiry is not a license to omit known people or lower their safeguards."},"headers":[],"relativePath":"en/concepts/affected-positions.md","filePath":"en/concepts/affected-positions.md"}'),n={name:"en/concepts/affected-positions.md"};function r(s,e,p,c,d,l){return o(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="trace-affected-positions-proportionately-without-shrinking-protection" tabindex="-1">Trace affected positions proportionately without shrinking protection <a class="header-anchor" href="#trace-affected-positions-proportionately-without-shrinking-protection" aria-label="Permalink to &quot;Trace affected positions proportionately without shrinking protection&quot;">​</a></h1><p><strong>A stopping rule for further inquiry is not a license to omit known people or lower their safeguards.</strong></p><p>Directly affected positions, known or raised low-power positions, and positions explicitly required by the application module must be listed in full. Proportionality governs the further tracing of indirect and more distant effects, taking severity, irreversibility, scale, accumulation, and power differences into account.</p><p>Further tracing may stop when it can no longer reasonably change the judgment, comparison of options, or protection arrangements. Record channels searched, positions consulted, and remaining unknowns. Include an undeclared channel raised by others or state the reason for not adopting it. The grounds must be published in advance and open to appeal; a beneficiary of a narrow boundary cannot decide it alone, and high-impact cases or conflicts require independent review.</p><p>An unknown reasonably capable of revealing a failure of the protection floor or changing the option comparison blocks the affected part of adoption until evidence is added, the option is narrowed, or protection with separate grounds is in place. Other unknowns remain visible with observation and renewed-identification conditions. Later-discovered positions retain the same appeal, correction, and remedy rights without proving they were foreseeable.</p><h2 id="keep-these-judgments-separate" tabindex="-1">Keep these judgments separate <a class="header-anchor" href="#keep-these-judgments-separate" aria-label="Permalink to &quot;Keep these judgments separate&quot;">​</a></h2><div class="xk-table"><table><thead><tr><th>Proportionate identification</th><th>Protection of identified positions</th></tr></thead><tbody><tr><td>Limits further tracing of indirect and distant positions on explicit grounds.</td><td>Is not reduced by that tracing limit.</td></tr></tbody></table></div><h2 id="teaching-example-a-service-relocation-and-a-missing-user-group" tabindex="-1">Teaching example: a service relocation and a missing user group <a class="header-anchor" href="#teaching-example-a-service-relocation-and-a-missing-user-group" aria-label="Permalink to &quot;Teaching example: a service relocation and a missing user group&quot;">​</a></h2><p>Suppose direct users are listed and a low-power group is raised by an advocate. That group cannot be omitted because it is costly to contact. More remote effects may use the proportionate tracing rule, with the basis open to challenge.</p><p><strong>Assumptions:</strong> Hypothetical proposal; no actual service or group is evaluated.</p><p><strong>Boundary:</strong> Known harm cannot be left unprotected merely because all distant effects cannot be exhaustively mapped.</p><h2 id="check-your-reading" tabindex="-1">Check your reading <a class="header-anchor" href="#check-your-reading" aria-label="Permalink to &quot;Check your reading&quot;">​</a></h2><p><strong>Are harms of keeping the status quo exempt from this inquiry?</strong></p><p>No. No action and maintaining the status quo carry the same responsibility to identify affected positions.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li><p>Do not apply the proportional stopping rule to the categories that must be fully listed.</p></li><li><p>Distinguish blocking unknowns from other registered unknowns; do not declare every gap harmless.</p></li></ul><p>Read the complete <a href="/xi-kari-skill/handbook/en/theory/part-14.html#section-14-4-1">source section §14.4.1</a> and its guide. This explanation follows theory v2; the <a href="/xi-kari-skill/handbook/en/downloads.html">Chinese original</a> remains authoritative.</p>',17)])])}const f=t(n,[["render",r]]);export{u as __pageData,f as default};
